<?php
if(PHP_SAPI!=='cli'){http_response_code(404);exit;}if(!in_array('--confirm',$argv,true)){fwrite(STDERR,"Uso: php database/backfill_autocontrollo_fire.php --confirm\n");exit(2);}
require_once __DIR__.'/../core/settings.php';require_once __DIR__.'/../core/autocontrollo_fire.php';$pdo=db();ensure_autocontrollo_fire_inspections_tables($pdo);$range=get_summer_season_range($pdo);$today=(new DateTimeImmutable('today',new DateTimeZone('Europe/Rome')))->format('Y-m-d');$dates=array_values(array_filter(autocontrollo_fire_schedule($range),static fn($date)=>$date<=$today));$items=$pdo->query('SELECT id,extinguisher_type,capacity_kg FROM autocontrollo_fire_extinguishers ORDER BY extinguisher_type,id')->fetchAll(PDO::FETCH_ASSOC);if(!$items)throw new RuntimeException('Nessun estintore configurato.');
$pdo->beginTransaction();try{$find=$pdo->prepare('SELECT id FROM autocontrollo_fire_inspections WHERE season_start=? AND season_end=? AND scheduled_date=?');$create=$pdo->prepare("INSERT INTO autocontrollo_fire_inspections(season_start,season_end,scheduled_date,status,started_at,completed_at)VALUES(?,?,?,'completata',?,?)");$complete=$pdo->prepare("UPDATE autocontrollo_fire_inspections SET status='completata',completed_at=? WHERE id=?");$delete=$pdo->prepare('DELETE FROM autocontrollo_fire_inspection_results WHERE inspection_id=?');$insert=$pdo->prepare('INSERT INTO autocontrollo_fire_inspection_results(inspection_id,extinguisher_id,extinguisher_label,extinguisher_type,capacity_kg,sort_order,is_suitable,checked_at)VALUES(?,?,?,?,?,?,1,?)');$count=0;foreach($dates as $date){$at=$date.' 09:00:00';$find->execute([$range['start'],$range['end'],$date]);$id=(int)($find->fetchColumn()?:0);if(!$id){$create->execute([$range['start'],$range['end'],$date,$at,$at]);$id=(int)$pdo->lastInsertId();}else{$complete->execute([$at,$id]);$delete->execute([$id]);}foreach($items as $i=>$item){$insert->execute([$id,$item['id'],$item['id'],$item['extinguisher_type'],$item['capacity_kg'],$i+1,$at]);$count++;}}$pdo->commit();printf("Completato: %d procedure e %d verifiche impostate su Sì.\n",count($dates),$count);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
